<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\PakistanErpRepository;
final class ParentPortalController extends PortalController{
public function index(Request$q):Response{$x=$this->identity();if(!$x||$x['audience']!=='parent')return$this->forbidden();$r=new PakistanErpRepository($this->app->database());return$this->portalView('portal/parent/dashboard','parent',['pageTitle'=>'My Children','pageDescription'=>'Linked student records','activeMenu'=>'portal-dashboard','activeSubmenu'=>'','guardian'=>$x['record'],'children'=>$r->guardianChildren((int)$x['record']['id'],$x['instituteId']),'instituteId'=>$x['instituteId']]);}
public function child(Request$q):Response{$x=$this->identity();if(!$x||$x['audience']!=='parent')return$this->forbidden();$r=new PakistanErpRepository($this->app->database());$child=$r->guardianChild((int)$x['record']['id'],(int)$q->route('id'),$x['instituteId']);if(!$child)return Response::html('Student not found',404);$portal=$this->repo();return$this->portalView('portal/parent/child','parent',['pageTitle'=>$child['student_name'],'pageDescription'=>'Child academic and financial overview','activeMenu'=>'portal-dashboard','activeSubmenu'=>'','guardian'=>$x['record'],'student'=>$child,'attendance'=>$portal->studentAttendanceSummary((int)$child['id'],date('Y-01-01'),date('Y-m-d')),'invoices'=>$portal->studentInvoices((int)$child['id']),'fees'=>$portal->studentFeeTotals((int)$child['id']),'homework'=>$portal->studentHomework((int)$child['class_id'],$x['instituteId']),'results'=>$portal->studentExamResults((int)$child['id'],$x['instituteId']),'tests'=>$portal->studentClassTests((int)$child['id'],$x['instituteId']),'instituteId'=>$x['instituteId']]);}}
